  "implementation": "def solve(case):
    # Extract required fields
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Validate lengths
    if not isinstance(word_token_indices, list) or not isinstance(word_labels, list):
        raise ValueError("word_token_indices and word_labels must be lists")
    if len(word_token_indices) != len(word_labels):
        raise ValueError("Mismatch between number of word groups and word labels")

    # Initialize token_labels with None to detect gaps/overlaps
    token_labels = [None] * token_count

    for idx, indices in enumerate(word_token_indices):
        label = word_labels[idx]
        if not isinstance(indices, list):
            raise ValueError(f"word_token_indices[{idx}] is not a list")
        for tidx in indices:
            if not isinstance(tidx, int):
                raise ValueError(f"Token index {tidx} is not an integer")
            if tidx < 0 or tidx >= token_count:
                raise ValueError(f"Token index {tidx} out of range [0, {token_count-1}]")
            if token_labels[tidx] is not None:
                raise ValueError(f"Overlapping token index {tidx}")
            token_labels[tidx] = label

    # Check for uncovered tokens
    for i, lbl in enumerate(token_labels):
        if lbl is None:
            raise ValueError(f"Token index {i} is not covered by any word group")

    # Build kept_indices (tokens with label == 1)
    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
